Looking at the implementation and ticket requirements, I need to write comprehensive tests covering:

1. Basic allow/deny decisions and deny-overrides logic
2. Principal matching (*, user:, role:)
3. Action/resource pattern matching (* and trailing *)
4. Case sensitivity
5. Input validation
6. Edge cases

Let me create a focused test suite with 8-20 test functions:

```json
{"code": "import impl
import pytest


def test_empty_policies_denies():
    """With no policies, request is denied."""
    request = {'subject': 'alice', 'roles': [], 'action': 's3:GetObject', 'resource': 'bucket/file'}
    assert impl.authorize(request, []) == 'DENY'


def test_single_allow_matches():
    """Single matching ALLOW policy grants access."""
    request = {'subject': 'alice', 'roles': [], 'action': 's3:GetObject', 'resource': 'bucket/file'}
    policy = {'effect': 'ALLOW', 'principal': 'user:alice', 'action': 's3:GetObject', 'resource': 'bucket/file'}
    assert impl.authorize(request, [policy]) == 'ALLOW'


def test_deny_overrides_allow():
    """DENY overrides ALLOW regardless of order."""
    request = {'subject': 'alice', 'roles': ['contractor'], 'action': 'docs:Read', 'resource': 'docs/reports/Q1'}
    allow = {'effect': 'ALLOW', 'principal': 'user:alice', 'action': 'docs:Read', 'resource': 'docs/reports/Q1'}
    deny = {'effect': 'DENY', 'principal': 'role:contractor', 'action': 'docs:Read', 'resource': 'docs/reports/Q1'}
    # Test both orderings
    assert impl.authorize(request, [allow, deny]) == 'DENY'
    assert impl.authorize(request, [deny, allow]) == 'DENY'


def test_wildcard_principal():
    """Principal '*' matches any request."""
    request = {'subject': 'alice', 'roles': [], 'action': 'read', 'resource': 'file'}
    policy = {'effect': 'ALLOW', 'principal': '*', 'action': 'read', 'resource': 'file'}
    assert impl.authorize(request, [policy]) == 'ALLOW'


def test_user_principal():
    """Principal 'user:subject' matches exactly that subject."""
    request = {'subject': 'alice', 'roles': [], 'action': 'read', 'resource': 'file'}
    policy = {'effect': 'ALLOW', 'principal': 'user:alice', 'action': 'read', 'resource': 'file'}
    assert impl.authorize(request, [policy]) == 'ALLOW'

    # Different subject should not match
    request2 = {'subject': 'bob', 'roles': [], 'action': 'read', 'resource': 'file'}
    assert impl.authorize(request2, [policy]) == 'DENY'


def test_role_principal():
    """Principal 'role:name' matches if that role is in request roles."""
    request = {'subject': 'alice', 'roles': ['admin'], 'action': 'read', 'resource': 'file'}
    policy = {'effect': 'ALLOW', 'principal': 'role:admin', 'action': 'read', 'resource': 'file'}
    assert impl.authorize(request, [policy]) == 'ALLOW'

    # Missing role should not match
    request2 = {'subject': 'alice', 'roles': ['user'], 'action': 'read', 'resource': 'file'}
    assert impl.authorize(request2, [policy]) == 'DENY'


def test_principal_not_pattern():
    """Principal 'user:al*' is literal, not a glob pattern."""
    request = {'subject': 'alice', 'roles': [], 'action': 'read', 'resource': 'file'}
    policy = {'effect': 'ALLOW', 'principal': 'user:al*', 'action': 'read', 'resource': 'file'}
    assert impl.authorize(request, [policy]) == 'DENY'


def test_action_patterns():
    """Action patterns: * matches all, trailing * is prefix, non-final * is literal."""
    request = {'subject': 'alice', 'roles': [], 'resource': 'file'}

    # * matches everything
    policy = {'effect': 'ALLOW', 'principal': '*', 'action': '*', 'resource': 'file'}
    assert impl.authorize({**request, 'action': 'anything'}, [policy]) == 'ALLOW'

    # Prefix match with trailing *
    policy = {'effect': 'ALLOW', 'principal': '*', 'action': 's3:Get*', 'resource': 'file'}
    assert impl.authorize({**request, 'action': 's3:GetObject'}, [policy]) == 'ALLOW'
    assert impl.authorize({**request, 'action': 's3:Get'}, [policy]) == 'ALLOW'

    # Non-final * is literal
    policy = {'effect': 'ALLOW', 'principal': '*', 'action': 's3:*Object', 'resource': 'file'}
    assert impl.authorize({**request, 'action': 's3:*Object'}, [policy]) == 'ALLOW'
    assert impl.authorize({**request, 'action': 's3:GetObject'}, [policy]) == 'DENY'


def test_resource_patterns():
    """Resource patterns: * matches all, trailing * is prefix."""
    request = {'subject': 'alice', 'roles': [], 'action': 'read'}

    # * matches everything
    policy = {'effect': 'ALLOW', 'principal': '*', 'action': 'read', 'resource': '*'}
    assert impl.authorize({**request, 'resource': 'anything'}, [policy]) == 'ALLOW'

    # Prefix match with trailing *
    policy = {'effect': 'ALLOW', 'principal': '*', 'action': 'read', 'resource': 'docs/*'}
    assert impl.authorize({**request, 'resource': 'docs/file'}, [policy]) == 'ALLOW'
    assert impl.authorize({**request, 'resource': 'docs/reports/Q1'}, [policy]) == 'ALLOW'


def test_case_sensitivity():
    """Matching is case-sensitive for all fields."""
    request = {'subject': 'alice', 'roles': [], 'action': 'Read', 'resource': 'file'}

    # Case mismatch in action
    policy = {'effect': 'ALLOW', 'principal': 'user:alice', 'action': 'read', 'resource': 'file'}
    assert impl.authorize(request, [policy]) == 'DENY'

    # Case mismatch in subject
    policy2 = {'effect': 'ALLOW', 'principal': 'user:Alice', 'action': 'Read', 'resource': 'file'}
    assert impl.authorize(request, [policy2]) == 'DENY'


def test_request_validation_missing_fields():
    """Request must have all required fields: subject, roles, action, resource."""
    valid = {'subject': 'alice', 'roles': [], 'action': 'read', 'resource': 'file'}

    for field in ['subject', 'roles', 'action', 'resource']:
        invalid = {k: v for k, v in valid.items() if k != field}
        with pytest.raises(ValueError):
            impl.authorize(invalid, [])


def test_request_validation_roles_must_be_list():
    """Request 'roles' must be a list."""
    request = {'subject': 'alice', 'roles': 'admin', 'action': 'read', 'resource': 'file'}
    with pytest.raises(ValueError):
        impl.authorize(request, [])


def test_policy_validation_missing_fields():
    """Policy must have all required fields: effect, principal, action, resource."""
    valid = {'effect': 'ALLOW', 'principal': '*', 'action': 'read', 'resource': 'file'}
    request = {'subject': 'alice', 'roles': [], 'action': 'read', 'resource': 'file'}

    for field in ['effect', 'principal', 'action', 'resource']:
        invalid = {k: v for k, v in valid.items() if k != field}
        with pytest.raises(ValueError):
            impl.authorize(request, [invalid])


def test_policy_validation_effect():
    """Policy effect must be exactly 'ALLOW' or 'DENY'."""
    request = {'subject': 'alice', 'roles': [], 'action': 'read', 'resource': 'file'}

    for effect in ['allow', 'Allow', 'PERMIT', 'YES', '']:
        policy = {'effect': effect, 'principal': '*', 'action': 'read', 'resource': 'file'}
        with pytest.raises(ValueError, match=repr(effect)):
            impl.authorize(request, [policy])


def test_multiple_roles_and_policies():
    """Request with multiple roles works correctly."""
    request = {'subject': 'alice', 'roles': ['user', 'admin', 'developer'], 'action': 'read', 'resource': 'file'}

    # Should match on admin role
    policy = {'effect': 'ALLOW', 'principal': 'role:admin', 'action': 'read', 'resource': 'file'}
    assert impl.authorize(request, [policy]) == 'ALLOW'

    # Should match on developer role
    policy2 = {'effect': 'ALLOW', 'principal': 'role:developer', 'action': 'read', 'resource': 'file'}
    assert impl.authorize(request, [policy2]) == 'ALLOW'


def test_non_matching_policies_ignored():
    """Non-matching policies don't affect decision."""
    request = {'subject': 'alice', 'roles': [], 'action': 'read', 'resource': 'file'}

    non_match_deny = {'effect': 'DENY', 'principal': 'user:bob', 'action': 'read', 'resource': 'file'}
    match_allow = {'effect': 'ALLOW', 'principal': 'user:alice', 'action': 'read', 'resource': 'file'}

    # Even though there's a DENY policy, it doesn't match so ALLOW wins
    assert impl.authorize(request, [non_match_deny, match_allow]) == 'ALLOW'


def test_validation_before_decision():
    """Invalid policies cause error even if they wouldn't match."""
    request = {'subject': 'alice', 'roles': [], 'action': 'read', 'resource': 'file'}

    # Invalid policy with principal that wouldn't match alice
    policy = {'effect': 'INVALID', 'principal': 'user:bob', 'action': 'read', 'resource': 'file'}
    with pytest.raises(ValueError):
        impl.authorize(request, [policy])


def test_empty_string_values():
    """Empty strings are valid for subject, action, resource."""
    request = {'subject': '', 'roles': [], 'action': '', 'resource': ''}
    policy = {'effect': 'ALLOW', 'principal': 'user:', 'action': '', 'resource': ''}
    assert impl.authorize(request, [policy]) == 'ALLOW'
"}
